def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)
    with io.open(os.path.join(root, SEEDER_PATH), encoding="utf-8") as f:
        seeder = f.read()

    if "pos_profile" in data:
        print("Already applied. Nothing to do.")
        return
    if '"3.145.0"' not in init:
        sys.exit("ABORT: not at v3.145.0.")

    old_order = 'ORDER = ["counter_system"]'
    new_order = 'ORDER = ["counter_system", "pos_profile"]'
    if seeder.count(old_order) != 1:
        sys.exit(f"ABORT: seeder ORDER anchor not found exactly once ({seeder.count(old_order)}).")

    problems = []
    if len(LESSONS) != 10:
        problems.append(f"  {len(LESSONS)} lessons (want 10 — the track's first deep module)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"POS 2: 10 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["pos_profile"] = {
        "title": "POS 2 — The Point of Sale Profile",
        "desc": "The track's first deep module: the counter's constitution at field depth — the ten-record groundwork with the sanity-check sale, items/prices/tax with the one-template-one-behaviour law, tab one's operating posture, the discount constitution and override economics, payments/returns/lay-by/staff purchase, the voucher tab's deliberate conservatism with Guarded Offline as a risk budget, integrations, the access rows normalised by mode, and the Power Approver table staffed and rehearsed.",
        "lessons": LESSONS,
        "questions": bank,
    }
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, SEEDER_PATH), "w", encoding="utf-8") as f:
        f.write(seeder.replace(old_order, new_order, 1))
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.145.0"', '"3.146.0"'))
    print("  data: POS 2 appended (10 chapters); seeder ORDER extended")
    print("wrote __version__ -> 3.146.0")


if __name__ == "__main__":
    main()
